  "package": "@astryxdesign/cli",
  "data": {
    "title": "Custom Variants",
    "content": [
      {
        "type": "prose",
        "text": "Themes can add new prop values to any component. Any `prop:value` key where the value isn't a built-in gets treated as a new variant. Use `astryx theme build` to generate TypeScript augmentations for type safety."
      },
      {
        "type": "code",
        "lang": "tsx",
        "code": "components: {\n  button: {\n    'variant:secondary': { backgroundColor: 'rgba(0,0,0,0.06)' },\n    'variant:primary-muted': {\n      backgroundColor: 'light-dark(#F2F4F6, #28292C)',\n      color: 'var(--color-text-primary)',\n    },\n  },\n  banner: {\n    'status:neutral': {\n      backgroundColor: 'var(--color-background-muted)',\n      color: 'var(--color-text-secondary)',\n    },\n  },\n}",
        "label": "Adding custom variants"
      },
      {
        "type": "code",
        "lang": "tsx",
        "code": "// TypeScript knows about 'primary-muted' after astryx theme build\n<Button variant=\"primary-muted\" label=\"Save draft\" />\n<Banner status=\"neutral\" title=\"Note\" />",
        "label": "Using custom variants"
      },
      {
        "type": "prose",
        "text": "Custom variants only work when the theme that defines them is active. The component's variant map is extended via module augmentation, with no changes to the component source needed."
      }
    ],
    "id": "custom-variants",
